PaintStatus paint_session_selection_mask(struct PaintCore *core,
                                         struct PaintSession *session,
                                         uint64_t publication,
                                         uint32_t index,
                                         uint8_t *bytes,
                                         uint32_t capacity,
                                         uint32_t *out_length);

/**
 * ABI 1.8: query one bounded selection step; inversion uses zero geometry.
 * # Safety
 * Initialize output size; index must belong to the same queried publication.
 */
PaintStatus paint_session_selection_step(struct PaintCore *core,
                                         struct PaintSession *session,
                                         uint64_t publication,
                                         uint32_t index,
                                         struct PaintSelectionStep *out);

/**
 * ABI 1.9: non-mutating full composite blend preview in view slot 0/1.
 * A regular set_viewport replaces/clears the override; requests retain normal generation semantics.
 * # Safety
 * Follow initialized viewport, writable output and session lifetime contracts.
 */
PaintStatus paint_session_set_blend_preview(struct PaintCore *core,
                                            struct PaintSession *session,
                                            uint64_t layer_id,
                                            uint32_t blend_mode,
                                            const struct PaintViewport *viewport,
                                            uint64_t *out_request);

/**
 * ABI 1.11: retarget the per-document history command limit. Accepted like a command and applied
 * in order on the session worker; a smaller limit evicts the oldest undo records and the history
 * boundary becomes unreachable (no fake initial state). Returns the accepted sequence.
 * # Safety
 * Follow session lifetime contracts; serialize with other submit calls for this session.
 */
PaintStatus paint_session_set_history_limit(struct PaintCore *core,
                                            struct PaintSession *handle,
                                            uint32_t max_commands,
                                            uint64_t *out_sequence);

/**
 * ABI 1.4: FIFO appearance edit; validate/copy DTO before return, actor enforces locks.
 * # Safety
 * Follow valid initialized input, writable sequence and session ownership contracts.
 */
PaintStatus paint_session_set_layer_appearance(struct PaintCore *core,
                                               struct PaintSession *session,
                                               uint64_t layer_id,
                                               const struct PaintLayerAppearance *options,
                                               uint64_t *out_sequence);

/**
 * ABI 1.7: FIFO clipping edit. base_layer_id must be 0; actor resolves adjacency.
 * # Safety
 * Initialize input DTO and writable sequence; follow session ownership contracts.
 */
PaintStatus paint_session_set_layer_clipping(struct PaintCore *core,
                                             struct PaintSession *session,
                                             uint64_t layer_id,
                                             const struct PaintLayerClipping *options,
                                             uint64_t *out_sequence);

/**
 * ABI 1.4: background raw layer preview using reserved view slot 2 or 3.
 * Read via the existing frame_info/read_frame functions; disable via set_viewport.
 * # Safety
 * Follow initialized input DTO, output sequence and handle ownership contracts.
 */
PaintStatus paint_session_set_layer_preview(struct PaintCore *core,
                                            struct PaintSession *session,
                                            uint64_t layer_id,
                                            const struct PaintViewport *viewport,
                                            uint64_t *out_request);

/**
 * Update one of four output slots without model computation. enabled=0 cancels/releases that view.
 * # Safety
 * Follow initialized viewport, document generation, and nonoverlapping output contracts.
 */
PaintStatus paint_session_set_viewport(struct PaintCore *core,
                                       struct PaintSession *handle,
                                       const struct PaintViewport *viewport,
                                       uint64_t *out_request);

/**
 * Copy a small command into Rust FIFO. OK means accepted, not completed; poll session_info.
 * Layer ID zero in Begin means the active layer at execution time. Overload rolls a stroke back.
 * # Safety
 * Initialize outer/nested DTO sizes, keep text valid for this call, serialize stroke input order.
 */
PaintStatus paint_session_submit(struct PaintCore *core,
                                 struct PaintSession *handle,
                                 const struct PaintCommand *command,
                                 uint64_t *out_sequence);

/**
 * Queue a transform operation. UPDATE alone requires geometry; input is copied.
 * # Safety
 * Valid owned handles, readable initialized DTO and writable nonoverlapping sequence.
 */
PaintStatus paint_session_transform(struct PaintCore *core,
                                    struct PaintSession *session,
                                    uint32_t kind,
                                    const struct PaintTransform *geometry,
                                    uint64_t *out_sequence);

/**
 * Read the published transform geometry without waiting for computation.
 * # Safety
 * Valid owned handles and writable initialized DTO.
 */
PaintStatus paint_session_transform_info(struct PaintCore *core,
                                         struct PaintSession *session,
                                         uint64_t publication,
                                         struct PaintTransform *out);

/**
 * ABI 1.3: inspect a candidate configuration without changing a running core. Worker thread only.
 * Validation creates a writable run and cleans marked unlocked stale runs; no document recovery.
 * # Safety
 * Follow initialized DTO and writable output contracts in contracts/abi.md.
 */
PaintStatus paint_storage_inspect(const struct PaintStorageOptions *options,
                                  struct PaintStorageInfo *out_info);

